from turtle import * from random import randint
groesse_schneeflocke = 6 anzahl_schneeflocken = 30
def haus(): # Quadrat for i in range(4): forward(60) left(90) # nach oben zum Dach left(90) forward(60) right(90) # Dach for i in range(3): forward(60) left(120) # zurück zum Startpunkt right(90) forward(60) left(90)
def baum(): pencolor('brown') pensize(6) left(90) forward(40) pencolor('green') dot(50) penup() back(40) pendown() right(90) pensize(1) pencolor('black')
def verschieben(): penup() forward(90) pendown()
def schneeflocke(): for i in range(6): forward(groesse_schneeflocke) left(45) forward(groesse_schneeflocke / 2) back(groesse_schneeflocke / 2) right(90) forward(groesse_schneeflocke / 2) back(groesse_schneeflocke / 2) left(45) forward(groesse_schneeflocke / 2) back(groesse_schneeflocke * 1.5) right(60)
# Vorbereitung fürs Zeichnen hideturtle() speed(100) penup() goto(-230, -50) pendown()
# Dorf zeichnen haus() verschieben() baum() verschieben() baum() verschieben() haus() verschieben() haus() verschieben() baum()
# Schneeflocken zeichnen for i in range(anzahl_schneeflocken): penup() goto(randint(-220, 220), randint(-220, 220)) pendown() schneeflocke()
